plist_t create_plist_string_node(const char **bnode, uint64_t size) {
    // Allocate memory for the new plist data
    plist_data_t *data = (plist_data_t *)malloc(sizeof(plist_data_t));
    if (!data) {
        // Allocation failed for data structure
        return NULL;
    }

    // Allocate memory for the string data
    char *str_data = (char *)malloc(size + 1);
    if (!str_data) {
        // Allocation failed for string
        free(data);
        return NULL;
    }

    // Copy the string data from the byte node
    memcpy(str_data, *bnode, size);
    str_data[size] = '\0'; // Null-terminate the string

    // Initialize the data structure
    data->length = size;
    data->data = str_data;

    // Create a new node containing the data
    plist_t node = create_plist_node(PLIST_STRING, data);
    if (!node) {
        // Failed to create node, clean up
        free(str_data);
        free(data);
    }

    return node;
}

plist_t parse_string_node(const char **bnode, uint64_t size) {
    char *str;
    plist_t node;
    uint64_t len;

    str = (char *)malloc(size + 1);
    if (!str) {
        // Allocation failed
        return NULL;
    }

    memcpy(str, *bnode, size);
    str[size] = '\0';
    len = size;

    node = plist_new_node();
    if (!node) {
        free(str);
        return NULL;
    }

    node->type = PLIST_STRING;
    node->data.string_val = str;
    node->data.string_len = len;

    return node;
}

